import{_ as p,l as o,o as a,c as n,v as r,p as s,x as i,d as l,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"ping / iperf","description":"","frontmatter":{"title":"ping / iperf","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/network-measurement.md","filePath":"cs/network-measurement.md","lastUpdated":1789023840000}'),h={name:"cs/network-measurement.md"};function f(u,e,T,m,_,E){const t=o("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="ping-iperf" tabindex="-1">ping / iperf <a class="header-anchor" href="#ping-iperf" aria-label="Permalink to &quot;ping / iperf&quot;">​</a></h1><div class="epigraph"><p>ping 用 ICMP 回显读可达与 RTT；iperf 用灌流读吞吐。一个测延迟样本，一个填满 $C$，两者一起才对得上 BDP 与膨胀。</p><footer>—— 据 RFC 792 ICMP Echo；iperf 工具通识；Kurose 测量节整理</footer></div><p><a href="/cs/ttl-traceroute">traceroute</a> 画路径。<a href="/cs/bandwidth-delay-product">BDP</a> 与 <a href="/cs/bufferbloat">缓冲膨胀</a> 要数。<a href="/cs/service-discovery">上一课</a> 结束分发。缺口是<strong>主动测量入门</strong>：Echo 与灌流。本课不把抓包写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口 up 不等于应用好。ping：RTT、丢、是否过滤。不能代表 TCP 吞吐。iperf：开窗口灌满，看 Gb/s，会制造膨胀与扰民。要同时看 ping 在灌流时是否炸——膨胀诊断。ECMP 下每次测量可能不同路。卫星：ping 已是数百毫秒下限。</p><p>不要把公网 iperf 当攻击。</p><p><span class="marginnote">ICMP 常被滤，TCP ping 变体存在。iperf3 是实现。本课钉方法。</span></p><h3 id="两把尺子" tabindex="-1">两把尺子 <a class="header-anchor" href="#两把尺子" aria-label="Permalink to &quot;两把尺子&quot;">​</a></h3><p>ping 看 RTT，iperf 看吞吐，合起来看队列。ICMP 可能被降级。单次结果受 ECMP 污染。要分布不要单点。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：控制面 traceroute / 数据面 ping / 灌流 iperf。画：空闲 RTT vs 负载 RTT。与 ABR 估计同类，一层工具。</p>',11)),(a(),s(d,null,{default:i(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PING%5B%22ICMP%20Echo%22%5D%20--%3E%20RTT%5B%22%E5%BB%B6%E8%BF%9F%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20IPERF%5B%22%E7%81%8C%E6%B5%81%22%5D%20--%3E%20THR%5B%22%E5%90%9E%E5%90%90%22%5D%0A%20%20BOTH%5B%22%E5%90%8C%E6%97%B6%22%5D%20--%3E%20BB%5B%22%E5%8F%91%E7%8E%B0%E8%86%A8%E8%83%80%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>QoS 可能把 ICMP 降级，ping 差而 TCP 好。RoCE 要用专门诊断。Maglev 后测量打到不同后端。DoH 不改 ping。权限：ping 要 raw socket 在某系统。</p><p>统计：一次 ping 无意义，要分布。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 OWAMP 的全部。抓包与 Wireshark 是下一课。后课默认：ping 看 RTT/可达；iperf 看吞吐；合起来看队列。</p><p>只报「带宽 1G」不报 RTT 是半张图。</p><p>上一课留下的缺口在本课收口；「ping / iperf」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/packet-capture">抓包与 Wireshark</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Echo 测延迟；灌流测吞吐。</li><li>负载下 ping 暴露膨胀。</li><li>过滤与 ECMP 使单次结果不可绝对化。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 792；测量实践。</li></ul>',10))])}const C=p(h,[["render",f]]);export{g as __pageData,C as default};
